/* One definition, two languages.  The assembler tolerates no integer suffix
   and C under -Wconversion wants one on every constant that reaches a
   uint32_t, so the suffix is applied by macro rather than by writing each
   constant twice.  ZX_C32 pastes the suffix, so its argument must be a single
   literal token; a composite value is written as (ZX_C32(0x3) << 3).  */

#ifdef __ASSEMBLER__
#  define ZX_BIT(n)     (1 << (n))
#  define ZX_C32(v)     v
#else
#  define ZX_BIT(n)     (1U << (n))
#  define ZX_C32(v)     v ## U
#endif

