#define ZX_ASM_EC_HVC               0x12
#define ZX_ASM_EC_PABT_ROUTED       0x20
#define ZX_ASM_EC_DABT_ROUTED       0x24

#define ZX_ASM_HVC_IMM_NOP          0x0000
#define ZX_ASM_HVC_IMM_YIELD        0x0001

#define ZX_ASM_VEC_RESET            0x00
#define ZX_ASM_VEC_UNDEF            0x04
#define ZX_ASM_VEC_SVC              0x08
#define ZX_ASM_VEC_PABT_HYP         0x0C
#define ZX_ASM_VEC_DABT_HYP         0x10
#define ZX_ASM_VEC_HYP_TRAP         0x14
#define ZX_ASM_VEC_IRQ              0x18
#define ZX_ASM_VEC_FIQ              0x1C

#define ZX_ASM_FAULT_OFF_CAPTURES      0
#define ZX_ASM_FAULT_OFF_VECTOR     4
#define ZX_ASM_FAULT_OFF_HSR        8
#define ZX_ASM_FAULT_OFF_HPFAR      12
#define ZX_ASM_FAULT_OFF_HDFAR      16
#define ZX_ASM_FAULT_OFF_HIFAR      20
